"""Generate the browser operation boundary and static-only preview server."""
import json

HEADER = '# Generated by scripts/build/generate_data_models.py; DO NOT EDIT.\n'


def generate(api):
    return {
        'web/execution/client.generated.js':'// Generated; DO NOT EDIT.\n'+CLIENT.replace('__OPERATIONS__',json.dumps(api['operations'])),
        'web/execution/worker.generated.js':'// Generated; DO NOT EDIT.\n'+WORKER,
        'scripts/dev/http_runtimes_generated.py':HEADER+STATIC,
    }


CLIENT = """(() => {
  'use strict';
  const operations=__OPERATIONS__;
  const workerURL=new URL('worker.generated.js',document.currentScript.src);
  function create(transport) {
    return Object.freeze(Object.fromEntries(Object.entries(operations).map(([name,spec]) =>
      [name,async(input,{raw=false}={})=>{
        if(spec.request) Declarations.assertShape(spec.request,input);
        else if(input!==undefined) throw new Error(name+': unexpected input');
        const text=await transport(name,input);
        const value=JSON.parse(text);
        return raw ? text : value;
      }]
    )));
  }
  let worker, failure;
  const pending=new Set();
  function fail(error) {
    failure=error; for(const reject of pending)reject(error);pending.clear();
    if(worker)worker.terminate();
  }
  function transport(operation,input) {
    if(failure)return Promise.reject(failure);
    if(!worker) {
      worker=new Worker(workerURL,{type:'module'});
      worker.onerror=event=>fail(new Error(event.message||'Execution worker failed'));
      worker.onmessageerror=()=>fail(new Error('Unreadable worker response'));
    }
    return new Promise((resolve,reject)=>{
      const channel=new MessageChannel();
      const finish=(error,text)=>{pending.delete(abort);channel.port1.close();error?reject(error):resolve(text);};
      const abort=error=>finish(error);
      pending.add(abort);
      channel.port1.onmessage=({data})=>{
        if(data.error)finish(new Error(data.error));
        else if(typeof data.json!=='string')finish(new Error('Invalid worker response'));
        else finish(null,data.json);
      };
      channel.port1.onmessageerror=()=>finish(new Error('Unreadable operation response'));
      worker.postMessage({operation,input:JSON.stringify(input??null)},[channel.port2]);
    });
  }
  globalThis.ExecutionClient=Object.freeze({create});
  globalThis.Execution=create(transport);
})();
"""

WORKER = """import {loadPyodide} from './runtime/pyodide.mjs';
const ready=(async()=>{
  const py=await loadPyodide({indexURL:new URL('./runtime/',import.meta.url).href});
  await py.loadPackage(['jsonschema','numpy']);
  const response=await fetch(new URL('./engine.zip',import.meta.url));
  if(!response.ok)throw Error('Engine package unavailable');
  py.unpackArchive(await response.arrayBuffer(),'zip',{extractDir:'/project'});
  await py.runPythonAsync("import sys; sys.path.insert(0, '/project'); from inside_inference.delivery.service import execute_json");
  return py;
})();
let queue=Promise.resolve();
onmessage=({data,ports})=>{
  const port=ports[0];
  queue=queue.then(async()=>{
    try {
      const py=await ready;
      py.globals.set('operation_name',data.operation);
      py.globals.set('operation_input',data.input);
      const json=await py.runPythonAsync('await execute_json(operation_name, operation_input)');
      port.postMessage({json});
    } catch(error) {port.postMessage({error:String(error)});}
    finally {port.close();}
  });
};
"""

STATIC = '''"""Static-only preview server. No numerical execution or API routes."""
from functools import partial
from http.server import ThreadingHTTPServer, SimpleHTTPRequestHandler
from pathlib import Path


class StaticHandler(SimpleHTTPRequestHandler):
    def __init__(self, *args, cors_origin=None, **kwargs):
        self.cors_origin = cors_origin
        super().__init__(*args, **kwargs)

    def end_headers(self):
        if self.cors_origin is not None:
            self.send_header('Access-Control-Allow-Origin', self.cors_origin)
        super().end_headers()

    def log_message(self, *args): pass

    def send_head(self):
        root = Path(self.directory).resolve()
        path = Path(self.translate_path(self.path)).resolve()
        if path.is_dir(): path = (path/'index.html').resolve()
        if not path.is_relative_to(root) or not path.is_file():
            self.send_error(404)
            return None
        return super().send_head()


def socket_server(address, *, directory, cors_origin=None):
    return ThreadingHTTPServer(address, partial(StaticHandler,directory=str(directory),cors_origin=cors_origin))
'''
